// === PURE NOVALANG REPLACEMENT: nova_tcsv_service.nova ===
// Replaces: CSV parsing, writing, filtering, column ops
// Builtins used: split, join

fn parse_csv(csv_text) {
    let lines = split(csv_text, "\n")
    let data = []
    for line in lines {
        let row = split(line, ",")
        append(data, row)
    }
    return data
}

fn write_csv(data) {
    let lines = []
    for row in data {
        let line = join(row, ",")
        append(lines, line)
    }
    return join(lines, "\n")
}

// Example usage
